head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[autoComplete > P > allOption]<br/>AutoComplete 컴포넌트에 '전체 선택'을 의미하는 아이템을 추가할지 설정합니다.",
    "validation" : [
        "'전체 선택' 아이템의 Label 은 변경할 수 없습니다.",
        "displayFormatter 속성의 사용자 정의 함수는 '전체 선택' 아이템에는 적용되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 아이템 DataList 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' baseNode="list" repeatNode="map" id="dlt_city">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_city.setJSON([
        { "label" : "Incheon", "value" : "3" },
        { "label" : "Seoul", "value" : "1" },
        { "label" : "Busan", "value" : "4" },
        { "label" : "Sejong", "value" : "2" }
    ]);

    // con_allOption 기본값 true
    con_allOption.setValue("2");

    // 아이템 확인 버튼 클릭 시 목록이 먼저 닫히므로 mousedown capture 단계에서 표시 아이템을 기록
    btn_getItemInfo.render.addEventListener("mousedown", scwin.captureListState, true);

    // comp 초기 생성
    scwin.comp_init();
};



// displayFormatter 사용자 정의 함수 : Label 뒤에 City 를 붙여 반환
scwin.fn_displayFormat = function (value) {
    return value + " City";
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제]\n- displayFormatter 함수는 Label 뒤에 City 를 붙여 반환\n- allOptionLabel 은 전체 선택 Label 변경 시도용 속성\n[절차]\n1. 화살표 버튼으로 목록을 연 상태에서 아이템 확인\n2. 목록에서 Seoul 선택 -> 아이템 확인\n3. 목록에서 -전체- 선택 -> 아이템 확인"', '', 'label1');

    let properties = {
        allOption : con_allOption.getText(),
        displayFormatter : con_displayFormatter.getValue(),
        allOptionLabel : con_allOptionLabel.getValue(),
    }

    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:itemset nodeset="data:dlt_city">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());
}



// 버튼 mousedown 시점(목록이 닫히기 전)의 리스트창 표시 아이템 기록
scwin.captureListState = function (e) {
    scwin.listState = null;
    let itemTableElem = document.querySelector("[id='" + target1.id + "_itemTable']");
    if (!itemTableElem || getComputedStyle(itemTableElem).display === "none" || getComputedStyle(itemTableElem).visibility === "hidden") {
        return;
    }
    let rowElems = itemTableElem.querySelectorAll("[id='" + target1.id + "_itemTable_main'] tr, li");
    scwin.listState = Array.prototype.filter.call(rowElems, function (row) {
        return row.offsetParent !== null;
    }).map(function (row) {
        return row.textContent;
    });
};



// 열린 리스트창의 표시 아이템과 선택 아이템의 화면 표시값 출력 (validation 1, 2)
scwin.btn_getItemInfo_onclick = function (e) {
    if (scwin.listState) {
        wf_body_bottom.getObj("scwin").setReturnValue("리스트창 아이템 : " + scwin.listState.join(" / "));
    }
    let labelElem = document.querySelector("[id='" + target1.id + "_label']");
    wf_body_bottom.getObj("scwin").setReturnValue("선택 아이템 : " + target1.getText() + " (" + target1.getValue() + ") -> 표시값 : " + (labelElem ? labelElem.textContent : ""));
};
